<?php
declare(strict_types=1);define('_GNUBOARD_',true);require __DIR__.'/../../bridge/popularity-core.php';require __DIR__.'/../../bridge/popularity-plays.php';
function check(bool $b,string $m):void{if(!$b)throw new RuntimeException($m);}
function video(string $id,int $views,?string $sid=null):array{return ['id'=>$id,'snippet'=>['channelId'=>NP_CHANNEL,'title'=>'EP.1 Song '.$id],'status'=>['privacyStatus'=>'public','embeddable'=>true],'statistics'=>['viewCount'=>(string)$views],'match'=>['songId'=>$sid,'status'=>'matched'],'sqlCategories'=>['your-story','cover-reborn']];}
$songs=['s'=>['title'=>'A','genre_id'=>'kpop-original','ep'=>1],'t'=>['title'=>'B','genre_id'=>'dreamy-deep-house','ep'=>2]];$raw=[];$members=[NP_STORIES=>[],NP_COVERS=>[],NP_MV=>[]];for($i=0;$i<35;$i++){$id=sprintf('%011d',$i);$raw[]=video($id,100-$i,$i%2?'s':'t');$members[NP_STORIES][]=$id;$members[NP_COVERS][]=$id;if($i<2)$members[NP_MV][]=$id;}
$raw[]=$raw[0];$bad=video('aaaaaaaaaaa',99999,'s');$bad['status']['privacyStatus']='private';$raw[]=$bad;$missing=video('bbbbbbbbbbb',1,'s');unset($missing['statistics']['viewCount']);$raw[]=$missing;
$lists=[];foreach(array_keys($members)as $pid)$lists[]=['id'=>$pid,'snippet'=>['channelId'=>NP_CHANNEL,'title'=>'Official'],'status'=>['privacyStatus'=>'public']];$lists[]=['id'=>'playlist123','snippet'=>['channelId'=>NP_CHANNEL,'title'=>'Continuous Listening'],'status'=>['privacyStatus'=>'public']];$members['playlist123']=['00000000000','00000000000','00000000001'];
$cats=[['category_id'=>'collection','parent_id'=>'kpop-original'],['category_id'=>'kpop-original','parent_id'=>null]];$b=np_build($raw,$songs,$lists,$members,['s'=>3,'t'=>5],$cats,['s'=>['kpop-original'],'t'=>['collection','kpop-original']]);
check($b['totals']['youtubeViews']===array_sum(range(66,100)),'dedup/public/missing metrics');check($b['totals']['jukeboxPlays']===8,'unique song plays in global aggregate');check($b['totals']['score']===$b['totals']['youtubeViews']+8,'combined score');check($b['groups']['playlists'][0]['youtubeViews']===199&&$b['groups']['playlists'][0]['jukeboxPlays']===8,'playlist sets');check(count($b['groups']['collections'])===1,'collection distinct');
$f=array_column($b['groups']['featured'],'videoId');foreach(['ep','stories','covers']as $type){check(count($b['groups'][$type])===10,'refill '.$type);check(!array_intersect($f,array_column($b['groups'][$type],'videoId')),'featured exclusion '.$type);}check(count($b['groups']['mv'])===2,'MV IDs remain distinct');
foreach([[5,2,true,'up',3],[2,4,true,'down',-2],[3,3,true,'same',0],[null,1,true,'new',null],[null,1,false,'unknown',null]]as [$prev,$rank,$has,$state,$d]){$m=np_movement($prev,$rank,$has);check($m['rankState']===$state&&$m['rankDelta']===$d,'movement');}
$r=np_order([['contentId'=>'z','score'=>10],['contentId'=>'a','score'=>10]]);check($r[0]['contentId']==='a','stable tie');
$s=['policy'=>np_json(np_defaults()),'status'=>'playing','reason'=>null,'started_at'=>100,'last_at'=>100,'last_position'=>0,'credited'=>0];$x=np_play_progress($s,10,'progress',110);check($x['credited']===10.0,'actual progress');$x=np_play_progress($s,300,'progress',110);check($x['credited']===0.0,'seek not credited');$x=np_play_progress($s,31,'progress',131);check($x['credited']===0.0,'gap not credited');$x=np_play_progress($s,10,'pause',110);check($x['credited']===0.0,'pause not credited');$x=np_play_progress($s,10,'error',110);check($x['status']==='excluded','failed playback');$s['status']='pending';$x=np_play_progress($s,30,'progress',130);check($x['credited']===0.0,'no verified stream no credit');
echo "PASS view/play sums, unique IDs/song sets, category overlap, movement, tie order, top10 refill, MV identity, stream proof, seeks, gaps, failures\n";
